namespace Contracts.Desktop.Operations;

using Contracts.Application.Operations;

public sealed class OperationsPageViewModel : ObservableObject, INavigationTarget
{
    private readonly OperationsService service; private readonly IPersianDateService dates;
    private readonly IConfirmationService confirmation; private readonly IFilePickerService files;
    private string section="amendments",error="",number="",date="",subject="",description="",attachment="",issueDate="",expiryDate="",dueDate="",sourcePath="",notes="";
    private bool busy; private long id,version,contractId,typeId,statusId,amount,vat,documentTypeId; private long? bankId; private int extensionDays,quality,time,financial,hse;
    private AmendmentDto? selectedAmendment;private GuaranteeDto? selectedGuarantee;private InvoiceDto? selectedInvoice;private DocumentDto? selectedDocument;private AlertDto? selectedAlert;private EvaluationDto? selectedEvaluation;

    public OperationsPageViewModel(OperationsService service,IPersianDateService dates,IConfirmationService confirmation,IFilePickerService files)
    {
        this.service=service;this.dates=dates;this.confirmation=confirmation;this.files=files;
        RefreshCommand=new AsyncRelayCommand(RefreshAsync);NewCommand=new RelayCommand(New);OpenCommand=new RelayCommand(Open);
        SaveCommand=new AsyncRelayCommand(SaveAsync);DeleteCommand=new AsyncRelayCommand(DeleteAsync);BrowseCommand=new RelayCommand(Browse);
        GenerateAlertsCommand=new AsyncRelayCommand(GenerateAlertsAsync);ResolveAlertCommand=new AsyncRelayCommand(ResolveAlertAsync);ReopenAlertCommand=new AsyncRelayCommand(ReopenAlertAsync);
    }

    public ObservableCollection<OperationContractOption> Contracts{get;}=[];public ObservableCollection<SimpleLookupDto> GuaranteeTypes{get;}=[];public ObservableCollection<SimpleLookupDto> GuaranteeStatuses{get;}=[];public ObservableCollection<SimpleLookupDto> InvoiceTypes{get;}=[];public ObservableCollection<SimpleLookupDto> PaymentStatuses{get;}=[];public ObservableCollection<SimpleLookupDto> DocumentTypes{get;}=[];public ObservableCollection<SimpleLookupDto> Banks{get;}=[];
    public ObservableCollection<AmendmentDto> Amendments{get;}=[];public ObservableCollection<GuaranteeDto> Guarantees{get;}=[];public ObservableCollection<InvoiceDto> Invoices{get;}=[];public ObservableCollection<DocumentDto> Documents{get;}=[];public ObservableCollection<AlertDto> Alerts{get;}=[];public ObservableCollection<EvaluationDto> Evaluations{get;}=[];
    public bool IsAmendments=>section=="amendments";public bool IsGuarantees=>section=="guarantees";public bool IsInvoices=>section=="invoices";public bool IsDocuments=>section=="documents";public bool IsAlerts=>section=="alerts";public bool IsEvaluation=>section=="evaluation";
    public bool IsBusy{get=>busy;private set=>SetProperty(ref busy,value);}public string ErrorMessage{get=>error;private set{if(SetProperty(ref error,value))OnPropertyChanged(nameof(HasError));}}public bool HasError=>!string.IsNullOrWhiteSpace(error);
    public long ContractId{get=>contractId;set=>SetProperty(ref contractId,value);}public long TypeId{get=>typeId;set=>SetProperty(ref typeId,value);}public long StatusId{get=>statusId;set=>SetProperty(ref statusId,value);}public long? BankId{get=>bankId;set=>SetProperty(ref bankId,value);}public long AmountRial{get=>amount;set{if(SetProperty(ref amount,value))OnPropertyChanged(nameof(InvoiceTotal));}}public long VatAmountRial{get=>vat;set{if(SetProperty(ref vat,value))OnPropertyChanged(nameof(InvoiceTotal));}}public long InvoiceTotal=>OperationsService.PreviewInvoiceTotal(AmountRial,VatAmountRial);public int TimeExtensionDays{get=>extensionDays;set=>SetProperty(ref extensionDays,value);}public long DocumentTypeId{get=>documentTypeId;set=>SetProperty(ref documentTypeId,value);}
    public string Number{get=>number;set=>SetProperty(ref number,value);}public string Date{get=>date;set=>SetProperty(ref date,value);}public string Subject{get=>subject;set=>SetProperty(ref subject,value);}public string Description{get=>description;set=>SetProperty(ref description,value);}public string AttachmentPath{get=>attachment;set=>SetProperty(ref attachment,value);}public string IssueDate{get=>issueDate;set=>SetProperty(ref issueDate,value);}public string ExpiryDate{get=>expiryDate;set=>SetProperty(ref expiryDate,value);}public string DueDate{get=>dueDate;set=>SetProperty(ref dueDate,value);}public string SourcePath{get=>sourcePath;set=>SetProperty(ref sourcePath,value);}public string Notes{get=>notes;set=>SetProperty(ref notes,value);}
    public int QualityScore{get=>quality;set{if(SetProperty(ref quality,value))OnPropertyChanged(nameof(EvaluationTotal));}}public int TimeScore{get=>time;set{if(SetProperty(ref time,value))OnPropertyChanged(nameof(EvaluationTotal));}}public int FinancialScore{get=>financial;set{if(SetProperty(ref financial,value))OnPropertyChanged(nameof(EvaluationTotal));}}public int HseScore{get=>hse;set{if(SetProperty(ref hse,value))OnPropertyChanged(nameof(EvaluationTotal));}}public decimal EvaluationTotal=>OperationsService.PreviewEvaluationTotal(QualityScore,TimeScore,FinancialScore,HseScore);
    public AmendmentDto? SelectedAmendment{get=>selectedAmendment;set=>SetProperty(ref selectedAmendment,value);}public GuaranteeDto? SelectedGuarantee{get=>selectedGuarantee;set=>SetProperty(ref selectedGuarantee,value);}public InvoiceDto? SelectedInvoice{get=>selectedInvoice;set=>SetProperty(ref selectedInvoice,value);}public DocumentDto? SelectedDocument{get=>selectedDocument;set=>SetProperty(ref selectedDocument,value);}public AlertDto? SelectedAlert{get=>selectedAlert;set=>SetProperty(ref selectedAlert,value);}public EvaluationDto? SelectedEvaluation{get=>selectedEvaluation;set=>SetProperty(ref selectedEvaluation,value);}
    public IAsyncRelayCommand RefreshCommand{get;}public IRelayCommand NewCommand{get;}public IRelayCommand OpenCommand{get;}public IAsyncRelayCommand SaveCommand{get;}public IAsyncRelayCommand DeleteCommand{get;}public IRelayCommand BrowseCommand{get;}public IAsyncRelayCommand GenerateAlertsCommand{get;}public IAsyncRelayCommand ResolveAlertCommand{get;}public IAsyncRelayCommand ReopenAlertCommand{get;}

    public void ActivateRoute(string route){section=route;OnPropertyChanged(nameof(IsAmendments));OnPropertyChanged(nameof(IsGuarantees));OnPropertyChanged(nameof(IsInvoices));OnPropertyChanged(nameof(IsDocuments));OnPropertyChanged(nameof(IsAlerts));OnPropertyChanged(nameof(IsEvaluation));New();}
    public async Task OnNavigatedToAsync(CancellationToken cancellationToken){OperationsReferenceData r=await service.ReferencesAsync(Section(),cancellationToken);Replace(Contracts,r.Contracts);Replace(GuaranteeTypes,r.GuaranteeTypes);Replace(GuaranteeStatuses,r.GuaranteeStatuses);Replace(InvoiceTypes,r.InvoiceTypes);Replace(PaymentStatuses,r.PaymentStatuses);Replace(DocumentTypes,r.DocumentTypes);Replace(Banks,r.Banks);New();await RefreshAsync(cancellationToken);}
    private async Task RefreshAsync(CancellationToken ct)=>await Run(async()=>{if(IsAmendments)Replace(Amendments,await service.AmendmentsAsync(null,ct));else if(IsGuarantees)Replace(Guarantees,await service.GuaranteesAsync(null,ct));else if(IsInvoices)Replace(Invoices,await service.InvoicesAsync(null,ct));else if(IsDocuments)Replace(Documents,await service.DocumentsAsync(null,ct));else if(IsAlerts)Replace(Alerts,await service.AlertsAsync(null,ct));else Replace(Evaluations,await service.EvaluationsAsync(null,ct));});
    private void New(){id=version=0;ContractId=Contracts.FirstOrDefault()?.Id??0;TypeId=IsGuarantees?GuaranteeTypes.FirstOrDefault()?.Id??0:InvoiceTypes.FirstOrDefault()?.Id??0;StatusId=IsGuarantees?GuaranteeStatuses.FirstOrDefault()?.Id??0:PaymentStatuses.FirstOrDefault()?.Id??0;DocumentTypeId=DocumentTypes.FirstOrDefault()?.Id??0;BankId=null;Number=Date=Subject=Description=AttachmentPath=IssueDate=ExpiryDate=DueDate=SourcePath=Notes="";AmountRial=VatAmountRial=0;TimeExtensionDays=QualityScore=TimeScore=FinancialScore=HseScore=0;}
    private void Open(){if(IsAmendments&&SelectedAmendment is{}a){id=a.Id;version=a.ConcurrencyVersion;ContractId=a.ContractId;Number=a.Number;Date=dates.Format(a.Date);Subject=a.Subject??"";AmountRial=a.AmountChangeRial;TimeExtensionDays=a.TimeExtensionDays;Description=a.Description??"";AttachmentPath=a.AttachmentPath??"";}else if(IsGuarantees&&SelectedGuarantee is{}g){id=g.Id;version=g.ConcurrencyVersion;ContractId=g.ContractId;TypeId=g.TypeId;StatusId=g.StatusId;Number=g.Number;BankId=g.BankId;IssueDate=dates.Format(g.IssueDate);ExpiryDate=dates.Format(g.ExpiryDate);AmountRial=g.AmountRial;Description=g.Description??"";}else if(IsInvoices&&SelectedInvoice is{}i){id=i.Id;version=i.ConcurrencyVersion;ContractId=i.ContractId;TypeId=i.TypeId;StatusId=i.PaymentStatusId;Number=i.Number;Date=dates.Format(i.Date);DueDate=i.DueDate.HasValue?dates.Format(i.DueDate.Value):"";AmountRial=i.AmountRial;VatAmountRial=i.VatAmountRial;Description=i.Description??"";}else if(IsDocuments&&SelectedDocument is{}d){id=d.Id;version=d.ConcurrencyVersion;ContractId=d.ContractId;DocumentTypeId=d.DocumentTypeId;SourcePath="";}else if(IsEvaluation&&SelectedEvaluation is{}e){id=e.Id;version=e.ConcurrencyVersion;ContractId=e.ContractId;Date=dates.Format(e.Date);QualityScore=e.QualityScore;TimeScore=e.TimeScore;FinancialScore=e.FinancialScore;HseScore=e.HseScore;Notes=e.Notes??"";}}
    private async Task SaveAsync(CancellationToken ct)=>await Run(async()=>{if(IsAmendments){AmendmentInput v=new(ContractId,Number,Parse(Date),Subject,AmountRial,TimeExtensionDays,Description,AttachmentPath);if(id==0)await service.CreateAmendmentAsync(v,ct);else await service.UpdateAmendmentAsync(new(id,version,v),ct);}else if(IsGuarantees){GuaranteeInput v=new(ContractId,TypeId,Number,BankId,Parse(IssueDate),Parse(ExpiryDate),AmountRial,StatusId,Description);if(id==0)await service.CreateGuaranteeAsync(v,ct);else await service.UpdateGuaranteeAsync(new(id,version,v),ct);}else if(IsInvoices){InvoiceInput v=new(ContractId,Number,Parse(Date),TypeId,AmountRial,VatAmountRial,ParseOptional(DueDate),StatusId,Description);if(id==0)await service.CreateInvoiceAsync(v,ct);else await service.UpdateInvoiceAsync(new(id,version,v),ct);}else if(IsDocuments){if(id==0)await service.UploadDocumentAsync(new(ContractId,DocumentTypeId,SourcePath),ct);else await service.ReplaceDocumentAsync(new(id,version,DocumentTypeId,SourcePath),ct);}else if(IsEvaluation){EvaluationInput v=new(ContractId,Parse(Date),QualityScore,TimeScore,FinancialScore,HseScore,Notes);if(id==0)await service.CreateEvaluationAsync(v,ct);else await service.UpdateEvaluationAsync(new(id,version,v),ct);}New();await RefreshAsync(ct);});
    private async Task DeleteAsync(CancellationToken ct){if(id==0||IsAlerts||!await confirmation.ConfirmAsync("رکورد انتخاب‌شده حذف شود؟",ct))return;await Run(async()=>{if(IsAmendments)await service.DeleteAmendmentAsync(id,version,ct);else if(IsGuarantees)await service.DeleteGuaranteeAsync(id,version,ct);else if(IsInvoices)await service.DeleteInvoiceAsync(id,version,ct);else if(IsDocuments)await service.DeleteDocumentAsync(id,version,ct);else await service.DeleteEvaluationAsync(id,version,ct);New();await RefreshAsync(ct);});}
    private void Browse(){string? selected=files.PickDocument();if(selected is not null)SourcePath=selected;}
    private async Task GenerateAlertsAsync(CancellationToken ct)=>await Run(async()=>{AlertGenerationResult r=await service.GenerateAlertsAsync(ct);ErrorMessage=$"ایجاد: {r.Created}، بازگشایی: {r.Reopened}، به‌روزرسانی: {r.Refreshed}، رفع خودکار: {r.Resolved}";Replace(Alerts,await service.AlertsAsync(null,ct));});
    private async Task ResolveAlertAsync(CancellationToken ct){if(SelectedAlert is null)return;await Run(async()=>{await service.ResolveAlertAsync(SelectedAlert.Id,SelectedAlert.ConcurrencyVersion,ct);Replace(Alerts,await service.AlertsAsync(null,ct));});}
    private async Task ReopenAlertAsync(CancellationToken ct){if(SelectedAlert is null)return;await Run(async()=>{await service.ReopenAlertAsync(SelectedAlert.Id,SelectedAlert.ConcurrencyVersion,ct);Replace(Alerts,await service.AlertsAsync(null,ct));});}
    private DateOnly Parse(string value)=>dates.TryParse(value,out DateOnly d)?d:throw new MasterDataValidationException(["تاریخ باید شمسی و به شکل yyyy/MM/dd باشد."]);private DateOnly? ParseOptional(string value)=>string.IsNullOrWhiteSpace(value)?null:Parse(value);
    private SecuritySection Section()=>section switch{"amendments"=>SecuritySection.Amendments,"guarantees"=>SecuritySection.Guarantees,"invoices"=>SecuritySection.Invoices,"documents"=>SecuritySection.Documents,"alerts"=>SecuritySection.Alerts,"evaluation"=>SecuritySection.Evaluation,_=>throw new InvalidOperationException("Unknown operational section.")};
    private async Task Run(Func<Task> action){IsBusy=true;ErrorMessage="";try{await action();}catch(Exception ex){ErrorMessage=MasterData.MasterDataErrorMapper.Map(ex);}finally{IsBusy=false;}}
    private static void Replace<T>(ObservableCollection<T> target,IEnumerable<T> source){target.Clear();foreach(T item in source)target.Add(item);}
}
